import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
    selector: 'app-presetselect',
    templateUrl: './presetselect.component.html',
    styleUrls: ['./presetselect.component.less']
})

export class PresetSelectComponent {
    @Input() data = [];
    @Output() changed = new EventEmitter<number>();
    @Input() presetIndex = 0;

    public preset = 0;

    lineClick(event, data): void {
        event.preventDefault();
        this.preset = data;
        this.changed.emit(this.preset);
    }

}
