import { Component, AfterContentInit, ViewChild } from '@angular/core';
import { NgForm } from '@angular/forms';
import { WsdataService } from '../wsdata.service';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
    selector: 'app-editlabel',
    templateUrl: './editlabel.component.html',
    styleUrls: ['./editlabel.component.less']
})
export class EditLabelComponent implements AfterContentInit {
    @ViewChild('settingsForm', {static: false}) public settingsForm: NgForm;
    public labelId = 0;
    public text = '';

    constructor(public wsData: WsdataService, private route: ActivatedRoute, private router: Router) {
        this.labelId = parseInt(this.route.snapshot.paramMap.get('id'), 10);
        this.wsData.subscribeNewData(() => this.newdata());
        if (this.wsData.layoutData.labels.length > this.labelId) {
            this.copyData();
        }
    }

    newdata(): void {
        if ((this.wsData.layoutData.labels.length > this.labelId) && (this.settingsForm.form.pristine)) {
            this.copyData();
        }
    }

    copyData(): void {
        this.text = this.wsData.layoutData.labels[this.labelId].text;
    }

    ngAfterContentInit(): void {

    }

    dataApply(): void {
        this.wsData.layoutData.labels[this.labelId].text = this.text;
        this.wsData.layoutData.dirty = 1;
        this.settingsForm.form.markAsPristine();
        this.router.navigate(['/edit']);
    }

    dataCancel(): void {
        this.settingsForm.form.markAsPristine();
        this.router.navigate(['/edit']);
    }

}
