import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { MainComponent } from './views/main.component';
import { SettingsComponent } from './views/settings.component';
import { SystemComponent } from './views/system.component';
import { StreamComponent } from './views/stream.component';
import { LayoutComponent } from './views/layout.component';
import { EditComponent } from './views/edit.component';
import { EditClockComponent } from './views/editclock.component';
import { EditLabelComponent } from './views/editlabel.component';

const routes: Routes = [
    { path: 'status', component: MainComponent },
    { path: 'settings', component: SettingsComponent },
    { path: 'system', component: SystemComponent },
    { path: 'stream', component: StreamComponent },
    { path: 'edit', component: LayoutComponent },
    { path: 'edit/window/:id', component: EditComponent },
    { path: 'edit/clock', component: EditClockComponent },
    { path: 'edit/label/:id', component: EditLabelComponent },
    { path: '**', redirectTo: 'status', pathMatch: 'full'},
];

@NgModule({
    imports: [ RouterModule.forRoot(routes, { useHash: true }) ],
    exports: [ RouterModule ]
})
export class AppRoutingModule {}
