import { Component, AfterContentInit, ViewChild } from '@angular/core';
import { NgForm } from '@angular/forms';
import { WsdataService } from '../wsdata.service';
import { WindowData } from '../datatypes';

@Component({
    selector: 'app-layout',
    templateUrl: './layout.component.html',
    styleUrls: ['./layout.component.less']
})
export class LayoutComponent implements AfterContentInit {
    public addType = 0;
    public grid = 0;
    public inputNumber = 8;
    @ViewChild('layoutForm', {static: false}) public layoutForm: NgForm;

    constructor(public wsData: WsdataService) {
        this.wsData.subscribeNewData(() => this.newdata());
        this.newdata();
    }

    newdata(): void {
        if (this.wsData.layoutData.dirty === 0) {
            if (this.wsData.layoutData.grid === 3) {
                this.grid = 0;
            } else if (this.wsData.layoutData.grid === 4) {
                this.grid = 1;
            } else if (this.wsData.layoutData.grid === 5) {
                this.grid = 2;
            } else if (this.wsData.layoutData.grid === 6) {
                this.grid = 3;
            } else {
                this.grid = 4;
            }
        }
    }

    ngAfterContentInit(): void {
    }

    newWindow(window: WindowData): void {
        this.wsData.addWindow(window, this.addType);
        this.wsData.layoutData.dirty = 1;
    }

    removeWindow(window: WindowData): void {
        this.wsData.removeWindow(window);
        this.wsData.layoutData.dirty = 1;
    }

    setGrid(value: number): void {
        if (value === 0) {
            this.wsData.setGrid(3);
        } else if (value === 1) {
            this.wsData.setGrid(4);
        } else if (value === 2) {
            this.wsData.setGrid(5);
        } else if (value === 3) {
            this.wsData.setGrid(6);
        } else {
            this.wsData.setGrid(12);
        }
        this.wsData.layoutData.dirty = 1;
    }

    dataApply(): void {
        this.wsData.sendSet();
    }

    dataCancel(): void {
        this.wsData.layoutReset();
    }

    public presetChanged(preset: number): void {
        this.wsData.sendPreset(preset);
    }

}
