import { Component, Input, Output, EventEmitter } from '@angular/core';
import { WsdataService } from '../wsdata.service';

@Component({
    selector: 'app-soloselect',
    templateUrl: './soloselect.component.html',
    styleUrls: ['./soloselect.component.less']
})

export class SoloSelectComponent {
    @Input() enable = 0;
    @Input() input = 0;
    @Input() data = [''];
    @Output() changed = new EventEmitter<{enable: number, input: number}>();

    constructor(public wsData: WsdataService) {
    }

    public soloClick(): void {
        if (this.enable) {
            this.enable = 0;
        } else {
            this.enable = 1;
        }
        this.onChange();
    }

    public btnClick(btn: number): void {
        this.input = btn;
        this.onChange();
    }

    private onChange(): void {
        this.changed.emit({
            enable: this.enable,
            input: this.input
        });
    }

}
